def simulate_natural_selection(population, generations, mutation_rate):
    import random

    def calculate_fitness(population):
        total_fitness = sum(population)
        return [value / total_fitness for value in population]

    def select_survivors(population, fitness):
        survivors = []
        cumulative_fitness = 0
        random_numbers = random.random() * sum(fitness)
        for i, fitness_value in enumerate(fitness):
            cumulative_fitness += fitness_value
            if random_numbers < cumulative_fitness:
                survivors.append(population[i])
                random_numbers -= cumulative_fitness
        return survivors

    def apply_mutation(organism):
        if random.random() < mutation_rate:
            return organism + random.choice([-1, 1])
        return organism

    population = population.copy()
    for _ in range(generations):
        fitness = calculate_fitness(population)
        survivors = select_survivors(population, fitness)
        mutated_survivors = [apply_mutation(organism) for organism in survivors]
        population = mutated_survivors

    return population

